(2598431, 355714, 48456, '<td valign="top">i like the colors. the only thing is that the first thing you see is the flower and then the stationery, whereas the subject itself should be stationery. one could always argue though that the decoration on stationery is also the stationery itself. in that case you get a 8 perhaps a boost later.</td>', 'i like the colors. the only thing is that the first thing you see is the flower and then the stationery, whereas the subject itself should be stationery. one could always argue though that the decoration on stationery is also the stationery itself. in that case you get a 8 perhaps a boost later.', '2006-07-07 18:43:07.000000', NULL, 1),
(2598436, 356384, 48456, '<td valign="top">nice decomposition of what can be considered to be stationery. if the spring was sharper... if it was just a little sharper. still good</td>', 'nice decomposition of what can be considered to be stationery. if the spring was sharper... if it was just a little sharper. still good', '2006-07-07 18:44:07.000000', NULL, 1),
(2598438, 358527, 48456, '<td valign="top">good idea, tape on the green cylinder is distracting.</td>', 'good idea, tape on the green cylinder is distracting.', '2006-07-07 18:44:41.000000', NULL, 1),
(2598441, 357630, 48456, '<td valign="top">i like this alot, 9.</td>', 'i like this alot, 9.', '2006-07-07 18:45:06.000000', NULL, 1),
