(2600329, 355631, 53147, '<td valign="top">I really expected to see alot of origami in this challenge. This is nice, sharp and clean. The black background was a good choice rather than a color. Keeps a nice minimalist feel and really highlights the bird well. Good job.</td>', 'I really expected to see alot of origami in this challenge. This is nice, sharp and clean. The black background was a good choice rather than a color. Keeps a nice minimalist feel and really highlights the bird well. Good job.', '2006-07-08 11:55:34.000000', NULL, 1),
(2600333, 358304, 53147, '<td valign="top">Funny concept on a depressing subject. The textures and shadows make this more than a crinkled paper shot and works quite well IMO.</td>', 'Funny concept on a depressing subject. The textures and shadows make this more than a crinkled paper shot and works quite well IMO.', '2006-07-08 11:56:45.000000', NULL, 1),
