(2601067, 357872, 61234, '<td valign="top">Excellent work. Unique and imaginative. Well done.</td>', 'Excellent work. Unique and imaginative. Well done.', '2006-07-08 18:24:43.000000', NULL, 1),
(2601150, 357532, 53147, '<td valign="top">Boy - you got me stumped on this one. Not even sure how it would fit the other stationary challenge let alone this one. Maybe the flower challenge? Probably getting alot of the dreaded DNMC comments though - so here is something different maybe. You have a good capture of the bee. Nice colors in the flowers but you really lose most of the impact with the size of the picture. There is a tutorial on this site abouut saving your pictures for the web to maximize the 150k within the 640pixel limit. At a larger size more detail and impact would have been had with this shot (even more so in the right challenge). If you are new here welcome to DPC and dont let the comments get you down. There is always the next challenge and the past ones get forgotten quick. If you have been around for a while then I ask "What are you thinking man?" Seriously, good luck on future challenges and find that tutorial.</td>', 'Boy - you got me stumped on this one. Not even sure how it would fit the other stationary challenge let alone this one. Maybe the flower challenge? Probably getting alot of the dreaded DNMC comments though - so here is something different maybe. You have a good capture of the bee. Nice colors in the flowers but you really lose most of the impact with the size of the picture. There is a tutorial on this site abouut saving your pictures for the web to maximize the 150k within the 640pixel limit. At a larger size more detail and impact would have been had with this shot (even more so in the right challenge). If you are new here welcome to DPC and dont let the comments get you down. There is always the next challenge and the past ones get forgotten quick. If you have been around for a while then I ask "What are you thinking man?" Seriously, good luck on future challenges and find that tutorial.', '2006-07-08 18:55:33.000000', NULL, 1),
(2601160, 358397, 53147, '<td valign="top">I wont speak those dreaded letters that I am sure you are reading alot of. I will comemnt as if this shot was in another challenge. I think the main issue with this shot is the blur up front. You have some cool patterns in the background that the blur works well on but the rope really needs to be sharp and in focus to have a good separation. The interest level overall is pretty low as well. The color stands out strong but a picture of hanging rope just isnt an attention grabber. Hope you arent too disheartened being in the wrong challenge - check closer next time and good luck in the future.</td>', 'I wont speak those dreaded letters that I am sure you are reading alot of. I will comemnt as if this shot was in another challenge. I think the main issue with this shot is the blur up front. You have some cool patterns in the background that the blur works well on but the rope really needs to be sharp and in focus to have a good separation. The interest level overall is pretty low as well. The color stands out strong but a picture of hanging rope just isnt an attention grabber. Hope you arent too disheartened being in the wrong challenge - check closer next time and good luck in the future.', '2006-07-08 18:58:52.000000', NULL, 1),
(2601547, 357532, 57224, '<td valign="top">oops</td>', 'oops', '2006-07-08 21:20:38.000000', NULL, 1),
(2601596, 358383, 57224, '<td valign="top">A different challenge would have been a better score. sorry</td>', 'A different challenge would have been a better score. sorry', '2006-07-08 21:42:15.000000', NULL, 1),
(2601602, 355759, 31467, '<td valign="top">I really like this one... it looks like you just rotated (or failed to rotate the image...  but it gives the illusion that the pencil is floating.</td>', 'I really like this one... it looks like you just rotated (or failed to rotate the image...  but it gives the illusion that the pencil is floating.', '2006-07-08 21:43:58.000000', NULL, 1),
