(2601623, 358359, 31467, '<td valign="top">I really like.  Are my eyes just playing a trick on me, or is the basket tilted?</td>', 'I really like.  Are my eyes just playing a trick on me, or is the basket tilted?', '2006-07-08 21:49:25.000000', NULL, 1),
(2601675, 356051, 48890, '<td valign="top">Generally, I''m quite tired of seeing shots of couloured pencils in challenges. But this one stands out.  Lovely bokeh in the background. -1 for cliche. 8</td>', 'Generally, I''m quite tired of seeing shots of couloured pencils in challenges. But this one stands out.  Lovely bokeh in the background. -1 for cliche. 8', '2006-07-08 22:05:52.000000', NULL, 1),
(2601683, 358607, 48890, '<td valign="top">Technical note: oversharpened, see the strong halos around objects.  Otherwise the shot doesn''t do much for me. 4</td>', 'Technical note: oversharpened, see the strong halos around objects.  Otherwise the shot doesn''t do much for me. 4', '2006-07-08 22:07:25.000000', NULL, 1),
(2601691, 357282, 48890, '<td valign="top">If yo udidn''t write that this is a paper roll, I would not see it: I see some strange 3D object.  Cool effect.  A tighter crop woudl be better, IMO.</td>', 'If yo udidn''t write that this is a paper roll, I would not see it: I see some strange 3D object.  Cool effect.  A tighter crop woudl be better, IMO.', '2006-07-08 22:09:58.000000', NULL, 1),
