(2602022, 358304, 35530, '<td valign="top">I''m sitting here reading the perfectly focused lettering, admiring the nice texture of the paper. Then I scroll down and catch the title. I nearly wet myself laughing. Nice job.</td>', 'I''m sitting here reading the perfectly focused lettering, admiring the nice texture of the paper. Then I scroll down and catch the title. I nearly wet myself laughing. Nice job.', '2006-07-08 23:46:56.000000', NULL, 1),
(2602032, 357437, 35530, '<td valign="top">Very nice background. Might have tried moving the diary to the left and cropping so the edge of your monitor isn''t visible.</td>', 'Very nice background. Might have tried moving the diary to the left and cropping so the edge of your monitor isn''t visible.', '2006-07-08 23:49:25.000000', NULL, 1),
(2602034, 358387, 60379, '<td valign="top">I love the whole feeling of this, but the wood has so much going on, that it makes it all a bit too busy.  My favorite so far tho!  Good job! 7</td>', 'I love the whole feeling of this, but the wood has so much going on, that it makes it all a bit too busy.  My favorite so far tho!  Good job! 7', '2006-07-08 23:49:43.000000', NULL, 1),
