(2602125, 357967, 60302, '<td valign="top">nice idea.</td>', 'nice idea.', '2006-07-09 00:22:49.000000', NULL, 1),
(2602389, 358538, 48228, '<td valign="top">One of the best ideas re stationery with the composition, with actually paper..... I hope you do well..... Love the touch with the rose petals.....</td>', 'One of the best ideas re stationery with the composition, with actually paper..... I hope you do well..... Love the touch with the rose petals.....', '2006-07-09 03:01:59.000000', NULL, 1),
(2602536, 356412, 61797, '<td valign="top">Nice idea for a photo.  Bit of a strange birdseye view, camera could have been brought down for a nicer effect and better shot of the "stationery".  Best solution for this photo, open up the aperture and focus on the primary elements of the photo.  Good texture shot of the old typewriter.  Keep em coming.</td>', 'Nice idea for a photo.  Bit of a strange birdseye view, camera could have been brought down for a nicer effect and better shot of the "stationery".  Best solution for this photo, open up the aperture and focus on the primary elements of the photo.  Good texture shot of the old typewriter.  Keep em coming.', '2006-07-09 06:12:44.000000', NULL, 1),
(2602543, 357062, 61797, '<td valign="top">Nice setup.  The top lighting is a bit strange, I think soft lighting would better represent your intentions.  Stationary is a bit washed out, easily corrected by a softer light source.  Portions of the table actually pass for satellites, I know they are not, but, if it can pass for a satellite it is one.  I am anxious to see your next shot, Good Job.</td>', 'Nice setup.  The top lighting is a bit strange, I think soft lighting would better represent your intentions.  Stationary is a bit washed out, easily corrected by a softer light source.  Portions of the table actually pass for satellites, I know they are not, but, if it can pass for a satellite it is one.  I am anxious to see your next shot, Good Job.', '2006-07-09 06:26:43.000000', NULL, 1),
(2602569, 358533, 61797, '<td valign="top">Simple, colorful, well composed.  Some of the marks on the pencils are distracting from your "colorful" shot.  Nice texture on the sharpened ends!  Would love to see the colors even brighter.  Nice photo.</td>', 'Simple, colorful, well composed.  Some of the marks on the pencils are distracting from your "colorful" shot.  Nice texture on the sharpened ends!  Would love to see the colors even brighter.  Nice photo.', '2006-07-09 07:02:27.000000', NULL, 1),
(2602578, 357532, 52074, '<td valign="top">Wrong category, huh?  :O)</td>', 'Wrong category, huh?  :O)', '2006-07-09 07:11:23.000000', NULL, 1),
(2602580, 357220, 52074, '<td valign="top">HaHa! Love the title, creative for both challenges going on.</td>', 'HaHa! Love the title, creative for both challenges going on.', '2006-07-09 07:12:44.000000', NULL, 1),
(2602581, 357809, 52074, '<td valign="top">This is like one of those things thast you look at and it moves....well, "I" see it moving....don''t you???? LOL. Great picture, totally.!!! 10</td>', 'This is like one of those things thast you look at and it moves....well, "I" see it moving....don''t you???? LOL. Great picture, totally.!!! 10', '2006-07-09 07:12:57.000000', NULL, 1),
(2602584, 357646, 61797, '<td valign="top">Interesting, could use more color, something eye catching, bright nail polish?  A different light scheme could work wonders.  What is above the to do or not to do note?  Is it a snake or reverse question mark?  It is distracting from your nice photo.  A few changes will bring you a long way.  I do like your concept.</td>', 'Interesting, could use more color, something eye catching, bright nail polish?  A different light scheme could work wonders.  What is above the to do or not to do note?  Is it a snake or reverse question mark?  It is distracting from your nice photo.  A few changes will bring you a long way.  I do like your concept.', '2006-07-09 07:13:41.000000', NULL, 1),
(2602585, 358607, 52074, '<td valign="top">Crisp and clear! Cute idea and a fav. Bumping</td>', 'Crisp and clear! Cute idea and a fav. Bumping', '2006-07-09 07:13:45.000000', NULL, 1),
(2602586, 355631, 52074, '<td valign="top">Used to love to do these things as a kid. Good choice of the B &amp; W.</td>', 'Used to love to do these things as a kid. Good choice of the B & W.', '2006-07-09 07:14:29.000000', NULL, 1),
(2602587, 358314, 52074, '<td valign="top">Creative and crisp macro here. Good job.</td>', 'Creative and crisp macro here. Good job.', '2006-07-09 07:14:32.000000', NULL, 1),
(2602588, 358223, 52074, '<td valign="top">The color tones give that feel of the era when these items were actually used. Good job.</td>', 'The color tones give that feel of the era when these items were actually used. Good job.', '2006-07-09 07:15:18.000000', NULL, 1),
(2602593, 357148, 52074, '<td valign="top">Nice. The all natural color tone of everything creates a soft view. Good capture.</td>', 'Nice. The all natural color tone of everything creates a soft view. Good capture.', '2006-07-09 07:17:07.000000', NULL, 1),
(2602596, 358341, 52074, '<td valign="top">Cute title. The simplicity here makes this a good photo IMO.</td>', 'Cute title. The simplicity here makes this a good photo IMO.', '2006-07-09 07:18:15.000000', NULL, 1),
(2602597, 356370, 52074, '<td valign="top">Creative entry. Like the effect of the candles with the color tones used.</td>', 'Creative entry. Like the effect of the candles with the color tones used.', '2006-07-09 07:18:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2602598, 354935, 52074, '<td valign="top">Nice clear shot. Love the sky in the b/g and thr crispness of the message in the bottle.</td>', 'Nice clear shot. Love the sky in the b/g and thr crispness of the message in the bottle.', '2006-07-09 07:19:33.000000', NULL, 1),
(2602600, 356051, 52074, '<td valign="top">Right! Bet you''ve gotten a couple of "been done before" comments, huh?  Nice choice of b/g and good symmetry in your composition. Bumping.</td>', 'Right! Bet you''ve gotten a couple of "been done before" comments, huh?  Nice choice of b/g and good symmetry in your composition. Bumping.', '2006-07-09 07:20:36.000000', NULL, 1),
(2602601, 356877, 61797, '<td valign="top">Nice photo, simplistic framing.  Subject matter too closely matches background in texture and contrast.  Looks like excessive noise in photo, although I''m sure it is the coloration, if it could pass for noise it is noise.  Your next entry will rock!</td>', 'Nice photo, simplistic framing.  Subject matter too closely matches background in texture and contrast.  Looks like excessive noise in photo, although I''m sure it is the coloration, if it could pass for noise it is noise.  Your next entry will rock!', '2006-07-09 07:23:11.000000', NULL, 1),
(2602610, 358341, 61797, '<td valign="top">Strange lighting, I think it''s too dark, the bright yellow may not help.  Items look as if they are floating above a desk.  I don''t think that''s the effect you were going for.  Shallow depth of field makes portions of the pen look out of focus.  Pen would look better if it had more contrast, no bar code exposed, etc.  Keep on dabbling with similar brights on darks, there is a winner to be had in the idea.</td>', 'Strange lighting, I think it''s too dark, the bright yellow may not help.  Items look as if they are floating above a desk.  I don''t think that''s the effect you were going for.  Shallow depth of field makes portions of the pen look out of focus.  Pen would look better if it had more contrast, no bar code exposed, etc.  Keep on dabbling with similar brights on darks, there is a winner to be had in the idea.', '2006-07-09 07:35:35.000000', NULL, 1),
(2602628, 358647, 61797, '<td valign="top">Nice Photo.  A bit washed out and harsh on subject matter.  Might do better as a detail shot.  Nice use of depth of field.  Interesting, mouse on tile.</td>', 'Nice Photo.  A bit washed out and harsh on subject matter.  Might do better as a detail shot.  Nice use of depth of field.  Interesting, mouse on tile.', '2006-07-09 08:06:24.000000', NULL, 1),
(2602631, 358304, 61797, '<td valign="top">Nice detail of the paper.  Nicely lit.  Could use more contrast.</td>', 'Nice detail of the paper.  Nicely lit.  Could use more contrast.', '2006-07-09 08:11:37.000000', NULL, 1),
(2602636, 357065, 61797, '<td valign="top">Photo does not look natural.  Logo at top looks like CGI, with tons of noise.  Massive satellite inside O.  Poor print type on stationery makes this photo look like it was taken with cheap camera.  It''s not the photographer or the camera it''s the subject matter.  This photo simply cannot pull off a distressed or antiqued look.  Anxious to see your next submission, if you try a new subject matter you may have much better luck.  Nice composition.  Good idea for a shot.</td>', 'Photo does not look natural.  Logo at top looks like CGI, with tons of noise.  Massive satellite inside O.  Poor print type on stationery makes this photo look like it was taken with cheap camera.  It''s not the photographer or the camera it''s the subject matter.  This photo simply cannot pull off a distressed or antiqued look.  Anxious to see your next submission, if you try a new subject matter you may have much better luck.  Nice composition.  Good idea for a shot.', '2006-07-09 08:23:44.000000', NULL, 1),
(2602660, 358680, 57224, '<td valign="top">I hope you don''t expect me to read any of your work!</td>', 'I hope you don''t expect me to read any of your work!', '2006-07-09 09:08:30.000000', NULL, 1),
(2602663, 355864, 57224, '<td valign="top">Well done. Hope you score as well as I think you deserve.</td>', 'Well done. Hope you score as well as I think you deserve.', '2006-07-09 09:10:06.000000', NULL, 1),
(2602665, 354935, 57224, '<td valign="top">Hope you score as well as I think you deserve. 10</td>', 'Hope you score as well as I think you deserve. 10', '2006-07-09 09:10:54.000000', NULL, 1),
(2602668, 356051, 57224, '<td valign="top">Just looked at your photo and upgraded you to 10. Great shot.</td>', 'Just looked at your photo and upgraded you to 10. Great shot.', '2006-07-09 09:12:19.000000', NULL, 1),
(2602673, 358541, 57224, '<td valign="top">Six? I gave you 10. Good one.</td>', 'Six? I gave you 10. Good one.', '2006-07-09 09:14:07.000000', NULL, 1),
(2602676, 358314, 57224, '<td valign="top">I like</td>', 'I like', '2006-07-09 09:15:01.000000', NULL, 1),
(2602678, 356024, 57224, '<td valign="top">I like</td>', 'I like', '2006-07-09 09:15:18.000000', NULL, 1),
(2602679, 358527, 47274, '<td valign="top">the first thing i saw was the tape on the green loop<br/>other then that i love it</td>', 'the first thing i saw was the tape on the green loopother then that i love it', '2006-07-09 09:15:27.000000', NULL, 1),
(2602680, 358405, 57224, '<td valign="top">Excellent idea</td>', 'Excellent idea', '2006-07-09 09:16:55.000000', NULL, 1),
(2602684, 355159, 57224, '<td valign="top">I like this photo, can''t think how it could be improved. Well done.</td>', 'I like this photo, can''t think how it could be improved. Well done.', '2006-07-09 09:17:51.000000', NULL, 1),
(2602686, 357809, 57224, '<td valign="top">Not sure if it actually stationery but scored you well anyway, I like the effect.</td>', 'Not sure if it actually stationery but scored you well anyway, I like the effect.', '2006-07-09 09:18:48.000000', NULL, 1),
(2602688, 355289, 57224, '<td valign="top">I like your choice of subject and title. Well done.</td>', 'I like your choice of subject and title. Well done.', '2006-07-09 09:19:42.000000', NULL, 1),
(2602689, 358631, 57224, '<td valign="top">I tried to do this with a staple remover but failed where you have succeeded, well done.</td>', 'I tried to do this with a staple remover but failed where you have succeeded, well done.', '2006-07-09 09:20:38.000000', NULL, 1),
(2602692, 354970, 57224, '<td valign="top">You have to do something like this to make paper interesting, well done.</td>', 'You have to do something like this to make paper interesting, well done.', '2006-07-09 09:21:30.000000', NULL, 1),
(2602694, 358696, 57224, '<td valign="top">The colours stand out well, good job.</td>', 'The colours stand out well, good job.', '2006-07-09 09:22:29.000000', NULL, 1),
(2602762, 358223, 61797, '<td valign="top">Beautifully done.  I love the soft lighting and the texture of the paper.  Nice composition, well placed articles.  Nice seal.  Great!!!</td>', 'Beautifully done.  I love the soft lighting and the texture of the paper.  Nice composition, well placed articles.  Nice seal.  Great!!!', '2006-07-09 10:10:54.000000', NULL, 1),
(2602776, 358696, 61797, '<td valign="top">Simple, colorful, dramatic.  Beautiful true black background.  Excellent!!!</td>', 'Simple, colorful, dramatic.  Beautiful true black background.  Excellent!!!', '2006-07-09 10:21:09.000000', NULL, 1),
(2602777, 356362, 61797, '<td valign="top">Nice lighting, nice use of space, great repetition, pattern etc.  Nice contrast from a simplistic pattern.  The red satellites on the pen could have been removed for an amazing photo.  Very well done!</td>', 'Nice lighting, nice use of space, great repetition, pattern etc.  Nice contrast from a simplistic pattern.  The red satellites on the pen could have been removed for an amazing photo.  Very well done!', '2006-07-09 10:21:17.000000', NULL, 1),
(2602778, 357519, 61797, '<td valign="top">Nice B&amp;W.  Nice lighting, great contrast.  Nice texture on the ruler, paper and the wheel.  The ribbon holder may be a bit too much "washed out dead space" and there is a strange square around "Dear Mom", which doesn''t look like it belongs, otherwise fantastico!  Keystroke in motion is a great adea, even better with slower shutter!  Nice!</td>', 'Nice B&W.  Nice lighting, great contrast.  Nice texture on the ruler, paper and the wheel.  The ribbon holder may be a bit too much "washed out dead space" and there is a strange square around "Dear Mom", which doesn''t look like it belongs, otherwise fantastico!  Keystroke in motion is a great adea, even better with slower shutter!  Nice!', '2006-07-09 10:21:23.000000', NULL, 1),
(2602779, 358541, 61797, '<td valign="top">Nice composition, nice colors, nice black.  Beautiful repetition.  The sharpened end of the yellows and pinks are beginning to wash out and loose detail, also, harsh flash is causing reflection on the pencils to the front and back of the photo.  Can you relocate the light source?  Four white pixels in the black center don''t do this photo justice.  Otherwise beautiful.</td>', 'Nice composition, nice colors, nice black.  Beautiful repetition.  The sharpened end of the yellows and pinks are beginning to wash out and loose detail, also, harsh flash is causing reflection on the pencils to the front and back of the photo.  Can you relocate the light source?  Four white pixels in the black center don''t do this photo justice.  Otherwise beautiful.', '2006-07-09 10:21:36.000000', NULL, 1),
(2602780, 358403, 61797, '<td valign="top">Nicely done, dramatic results.</td>', 'Nicely done, dramatic results.', '2006-07-09 10:21:44.000000', NULL, 1),
(2602782, 355831, 61797, '<td valign="top">Well framed, looks much better as a thumbnail due to excessive noise.  Grainy could look nice in another photo.  Edges of the paper were well done.  The greens have turned to blues in portions of the photo, which is distracting.  Background would be better if it were darker.  That said, nice idea, simple pattern makes a nice photo, I think you''re well on your way.  Good Job!</td>', 'Well framed, looks much better as a thumbnail due to excessive noise.  Grainy could look nice in another photo.  Edges of the paper were well done.  The greens have turned to blues in portions of the photo, which is distracting.  Background would be better if it were darker.  That said, nice idea, simple pattern makes a nice photo, I think you''re well on your way.  Good Job!', '2006-07-09 10:22:06.000000', NULL, 1),
(2602783, 356678, 61797, '<td valign="top">Nice contrast, nice use of grain, well composed.  The reflection from the doorknob is distracting as is the abundance of light coming through the door.  Correcting those two items would much improve this very nice photo.  Cool Photo!</td>', 'Nice contrast, nice use of grain, well composed.  The reflection from the doorknob is distracting as is the abundance of light coming through the door.  Correcting those two items would much improve this very nice photo.  Cool Photo!', '2006-07-09 10:22:17.000000', NULL, 1),
