(2610339, 358397, 57400, '<td valign="top">Wrong challenge or wrong spelling?</td>', 'Wrong challenge or wrong spelling?', '2006-07-11 08:44:19.000000', NULL, 1),
(2610340, 357062, 57400, '<td valign="top">The elements are clear, and the color and composition are decent, but it lacks something... maybe it looks too staged and not wite authentic.</td>', 'The elements are clear, and the color and composition are decent, but it lacks something... maybe it looks too staged and not wite authentic.', '2006-07-11 08:45:46.000000', NULL, 1),
