(2610376, 356051, 57400, '<td valign="top">Nicee pencils and photo and color and composition, but unrelated to the challenge as i understand it.</td>', 'Nicee pencils and photo and color and composition, but unrelated to the challenge as i understand it.', '2006-07-11 08:58:50.000000', NULL, 1),
(2610378, 358387, 57400, '<td valign="top">A bit on the over-exposed side for my taste, but the elements of the composition and their subject matter are clearly understood to relate to the challenge subject.</td>', 'A bit on the over-exposed side for my taste, but the elements of the composition and their subject matter are clearly understood to relate to the challenge subject.', '2006-07-11 09:00:01.000000', NULL, 1),
(2610379, 357630, 57400, '<td valign="top">Nice composition of an idea that is easy to comprehend, with a visual segue toward the subject matter of the challenge.</td>', 'Nice composition of an idea that is easy to comprehend, with a visual segue toward the subject matter of the challenge.', '2006-07-11 09:02:45.000000', NULL, 1),
