(2610387, 358623, 57400, '<td valign="top">Bad shot (HA!) and bad spellin''. Too bad about the pole stickin'' through yer friend''s image. Shoulda taken a second shot at it! You got the subject matter down good, pardner, but you missed yer target.</td>', 'Bad shot (HA!) and bad spellin''. Too bad about the pole stickin'' through yer friend''s image. Shoulda taken a second shot at it! You got the subject matter down good, pardner, but you missed yer target.', '2006-07-11 09:06:00.000000', NULL, 1),
(2610389, 358696, 57400, '<td valign="top">Lovely photo. Crisp, clear, colorful, concise and curly!</td>', 'Lovely photo. Crisp, clear, colorful, concise and curly!', '2006-07-11 09:06:44.000000', NULL, 1),
(2610391, 358048, 57400, '<td valign="top">Folded or unfolded, but not stationery.</td>', 'Folded or unfolded, but not stationery.', '2006-07-11 09:07:07.000000', NULL, 1),
(2610392, 356137, 57400, '<td valign="top">Staples, not stationery.</td>', 'Staples, not stationery.', '2006-07-11 09:07:26.000000', NULL, 1),
(2610393, 358074, 57400, '<td valign="top">The end of something, but not even remotely like stationery.</td>', 'The end of something, but not even remotely like stationery.', '2006-07-11 09:07:59.000000', NULL, 1),
