(2610401, 355573, 57400, '<td valign="top">Translated from the Japanese??? Something is unclear about this image, and I''m not clear on what it is. Seems apropos, even if it is stationery. Try a little harder to clarify the elements and get the language right/write.</td>', 'Translated from the Japanese??? Something is unclear about this image, and I''m not clear on what it is. Seems apropos, even if it is stationery. Try a little harder to clarify the elements and get the language right/write.', '2006-07-11 09:10:49.000000', NULL, 1),
(2610403, 357809, 57400, '<td valign="top">More paper torches... used to frighten paper chariots, but not identifiably stationery.</td>', 'More paper torches... used to frighten paper chariots, but not identifiably stationery.', '2006-07-11 09:11:34.000000', NULL, 1),
(2610408, 357549, 57400, '<td valign="top">On your mark, get set, go fix the crocked tip of your writing implement! the stationery will wait. Other than the disconcerting bend in the pen or brush tip, this is a photo of stationery by candlelight. So... so it is.</td>', 'On your mark, get set, go fix the crocked tip of your writing implement! the stationery will wait. Other than the disconcerting bend in the pen or brush tip, this is a photo of stationery by candlelight. So... so it is.', '2006-07-11 09:13:28.000000', NULL, 1),
(2610414, 354977, 57400, '<td valign="top">Interesting compilation of disparaging elements, but rather jumbled in outcome of the message. I''ll go for the scissors and we can play the game again.</td>', 'Interesting compilation of disparaging elements, but rather jumbled in outcome of the message. I''ll go for the scissors and we can play the game again.', '2006-07-11 09:14:57.000000', NULL, 1),
(2610417, 357519, 57400, '<td valign="top">How delightfully old-fashioned! Very clear photo in B&amp;W form. Effective use of elements and tight composition. Nice.</td>', 'How delightfully old-fashioned! Very clear photo in B&W form. Effective use of elements and tight composition. Nice.', '2006-07-11 09:16:11.000000', NULL, 1),
(2610423, 356980, 57400, '<td valign="top">Is this a sales pitch or an overstock problem? It''s certainly a nice selection of stationery, from a rather askance viewpoint. Almost pleasing, but ust not quite.</td>', 'Is this a sales pitch or an overstock problem? It''s certainly a nice selection of stationery, from a rather askance viewpoint. Almost pleasing, but ust not quite.', '2006-07-11 09:17:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2610426, 356085, 57400, '<td valign="top">Nice gesture, but it is not clear in relation to the challenge subject. Best wishes!</td>', 'Nice gesture, but it is not clear in relation to the challenge subject. Best wishes!', '2006-07-11 09:18:35.000000', NULL, 1),
(2610432, 355714, 57400, '<td valign="top">Looks like a yard sign... the colors are nice, but subject is ambiguous.</td>', 'Looks like a yard sign... the colors are nice, but subject is ambiguous.', '2006-07-11 09:19:18.000000', NULL, 1),
(2610435, 358699, 57400, '<td valign="top">So, where''s the stationery?</td>', 'So, where''s the stationery?', '2006-07-11 09:19:49.000000', NULL, 1),
(2610441, 356244, 57400, '<td valign="top">Dear -ery:<br/>     I''m sorry that you didn''t win.<br/>                           Sincerelly yours,<br/>                                 Fellow Challenge Entrant</td>', 'Dear -ery:     I''m sorry that you didn''t win.                           Sincerelly yours,                                 Fellow Challenge Entrant', '2006-07-11 09:21:17.000000', NULL, 1),
(2610447, 355759, 57400, '<td valign="top">The selected lements make a good attempt to meet the challenge, but they are not well-photographed nor well-placed. Keep trying.</td>', 'The selected lements make a good attempt to meet the challenge, but they are not well-photographed nor well-placed. Keep trying.', '2006-07-11 09:22:41.000000', NULL, 1),
(2610450, 355176, 57400, '<td valign="top">OK. this is a literal attempt to depict the subject. The light seems harsh and the magnifying lens seems unwarranted. A decent attempt though.</td>', 'OK. this is a literal attempt to depict the subject. The light seems harsh and the magnifying lens seems unwarranted. A decent attempt though.', '2006-07-11 09:23:54.000000', NULL, 1),
(2610452, 358405, 57400, '<td valign="top">So it is, but where''s the stationery?</td>', 'So it is, but where''s the stationery?', '2006-07-11 09:24:16.000000', NULL, 1),
(2610456, 358562, 57400, '<td valign="top">Looks like a good way to kill time and abuse stationery, but at least it is stationery.</td>', 'Looks like a good way to kill time and abuse stationery, but at least it is stationery.', '2006-07-11 09:25:14.000000', NULL, 1),
(2610465, 358359, 57400, '<td valign="top">I think this would have been much more effective if the papers had some writing on them. It is a lovely photo with a clear message about the failure of the paper to do something, but without any writing, their function as stationery is not clear.</td>', 'I think this would have been much more effective if the papers had some writing on them. It is a lovely photo with a clear message about the failure of the paper to do something, but without any writing, their function as stationery is not clear.', '2006-07-11 09:27:30.000000', NULL, 1),
(2610467, 357245, 57400, '<td valign="top">These are old and new writing implements, but where is the stationery?</td>', 'These are old and new writing implements, but where is the stationery?', '2006-07-11 09:27:59.000000', NULL, 1),
(2610472, 358223, 57400, '<td valign="top">In truth, these appear to be folded and sealed pieces of stationery. hooray! Color, lighting and composition add to the antiquated feel of the elements in the photo. Nicely done.</td>', 'In truth, these appear to be folded and sealed pieces of stationery. hooray! Color, lighting and composition add to the antiquated feel of the elements in the photo. Nicely done.', '2006-07-11 09:29:34.000000', NULL, 1),
(2610477, 355388, 57400, '<td valign="top">Ugh! Looks like mathematics... which is not the usual subject of correspondence upon stationery. Please don''t send any my way. A better use of the elements would do more justice to the challenge.</td>', 'Ugh! Looks like mathematics... which is not the usual subject of correspondence upon stationery. Please don''t send any my way. A better use of the elements would do more justice to the challenge.', '2006-07-11 09:30:59.000000', NULL, 1),
(2610481, 356384, 57400, '<td valign="top">There''s not going to be any writing going on here, I suppose, with or without stationery.</td>', 'There''s not going to be any writing going on here, I suppose, with or without stationery.', '2006-07-11 09:31:53.000000', NULL, 1),
(2610482, 358119, 57400, '<td valign="top">Strange take-off from the intended subject, if you ask me; but you didn''t.</td>', 'Strange take-off from the intended subject, if you ask me; but you didn''t.', '2006-07-11 09:32:44.000000', NULL, 1),
(2610485, 358452, 57400, '<td valign="top">Magnificent macro shot to convey the subject.</td>', 'Magnificent macro shot to convey the subject.', '2006-07-11 09:33:21.000000', NULL, 1),
(2610487, 357703, 57400, '<td valign="top">Oh, I just love calligraphy!!! It is only slightly off the subject of the challenge though. Alas.</td>', 'Oh, I just love calligraphy!!! It is only slightly off the subject of the challenge though. Alas.', '2006-07-11 09:34:17.000000', NULL, 1),
(2610491, 356534, 57400, '<td valign="top">Nice photo and compositon for another challenge. Should I have to POINT out it isn''t stationery?</td>', 'Nice photo and compositon for another challenge. Should I have to POINT out it isn''t stationery?', '2006-07-11 09:35:20.000000', NULL, 1),
