(2611666, 356024, 60862, '<td valign="top">Interesting angle.</td>', 'Interesting angle.', '2006-07-11 18:36:27.000000', NULL, 1),
(2611668, 358664, 60862, '<td valign="top">Nice idea. :)<br/> <br/>I lost the postcard in the background, though.  If you can, try reshooting it with the postcard against the plain sky or against a darker building, but not across building boundaries.</td>', 'Nice idea. :) I lost the postcard in the background, though.  If you can, try reshooting it with the postcard against the plain sky or against a darker building, but not across building boundaries.', '2006-07-11 18:37:25.000000', NULL, 1),
(2611670, 356534, 60862, '<td valign="top">Nice. :)</td>', 'Nice. :)', '2006-07-11 18:37:36.000000', NULL, 1),
