INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2908304, 357282, 55838, '<td valign="top">Very cool shot - a shame about the DQ.  It happens and like you said, at least it wasn''t a processing issue (although I think in many of those cases no one is intentionaly trying to get away with anything.  Sometimes just go a little too far or are not sure exactly where the boundaries are).  I figure I''ll get one at some point too unfortunately - happens to lots of folks.  Anyway - I really like this pic and voted it 7 during the challenge.  Great lighting and softness and the reflection really adds a cool dimension.</td>', 'Very cool shot - a shame about the DQ.  It happens and like you said, at least it wasn''t a processing issue (although I think in many of those cases no one is intentionaly trying to get away with anything.  Sometimes just go a little too far or are not sure exactly where the boundaries are).  I figure I''ll get one at some point too unfortunately - happens to lots of folks.  Anyway - I really like this pic and voted it 7 during the challenge.  Great lighting and softness and the reflection really adds a cool dimension.', '2006-10-08 14:53:59.000000', NULL, 0),
